pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint amount) public {
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        // Record depositsCount before sendMoney
        uint before = c.depositsCount();
        // Perform sendMoney (which may or may not trigger receive)
        c.sendMoney(target, amount);
        uint after = c.depositsCount();
        // General rule: if msg.sender is not owner, the call would revert, but we are owner
        // The only way depositsCount changes is if receive() is triggered, which happens when target is a contract with receive
        // Since we can't know if target has receive, we bound the rule: depositsCount must be either before (if no receive triggered during sendMoney call) or before+1 (if receive triggered)
        // In the reference, sendMoney via call may trigger receive, incrementing depositsCount by 0 or 1
        // In the mutant, receive always reverts, so depositsCount cannot increase
        assertTrue(after == before || after == before + 1);
    }
}

