pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Bound value to see overflow behavior, but not too large to exceed block gas
        _value = bound(_value, 0, type(uint256).max);
        vm.assume(_value == 0 || _value > 0); // any value allowed

        // First, we need to set up state so that depositsCount is large enough to overflow
        // The only way to increase depositsCount is via receive(), which requires sending ether
        // We can send small amounts many times, but fuzz won't loop. Instead, we directly manipulate
        // depositsCount is not settable externally, but we can use vm.store to set it high for testing
        // However, the rule must be observable through public getters. 
        // The simpler approach: test that when depositsCount is near max, sendMoney can still be called without revert

        // To make overflow possible, we can set depositsCount to type(uint256).max using vm.store
        // First, get the storage slot of depositsCount (slot 1 for C)
        vm.store(address(c), bytes32(uint256(1)), bytes32(type(uint256).max));

        // Now call sendMoney as owner
        vm.prank(c.owner());
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));

        // The reference C does not revert because require(depositsCount + 1 >= depositsCount) is true even on overflow
        // The mutant reverts because require(depositsCount + 1 > depositsCount) is false on overflow (0 > type(uint256).max is false)
        assertTrue(success, "sendMoney should not revert even with depositsCount at max");
    }
}

