import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 deposits, uint256 sendValue, address target) public {
        // Bound deposits to avoid unrealistic gas limits
        vm.assume(deposits < 1000);

        // Make deposits by sending ether to the contract
        for (uint256 i = 0; i < deposits; i++) {
            (bool success, ) = address(c).call{value: 1 wei}("");
            require(success);
        }

        // Record depositsCount after deposits
        uint256 countBefore = c.depositsCount();

        // Now call sendMoney (onlyOwner - so we need to be owner)
        // The owner is the deployer (this contract)
        vm.deal(address(this), sendValue);
        c.sendMoney{value: sendValue}(target, sendValue);

        // The invariant: depositsCount should not decrease and should be at least countBefore
        // If overflow occurred, depositsCount would wrap to a smaller value
        assertTrue(c.depositsCount() >= countBefore);
    }
}

