pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value > 0 && value <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        c.sendMoney(target, value);
        uint256 balanceAfter = address(c).balance;
        // The reference contract sets withdrawAll to transfer the full contract balance.
        // After a successful sendMoney, the contract’s balance decreases by exactly `value`.
        // The buggy contract’s withdrawAll sends zero, so the balance decrease is still exactly `value`.
        // However, the bug affects the behavior of withdrawAll but not the balance change of sendMoney.
        // So we need a different invariant: after any sendMoney, the next withdrawAll must drain all balance.
        // But we cannot call withdrawAll in the property because it resets the balance to zero.
        // Instead, we assert that the balance after sendMoney is correct: it equals (balanceBefore - value).
        // This holds for both P and M, so it's not sufficient.
        // Let's check the total deposits count instead: after a sendMoney, the count should be unchanged.
        // Still holds for both.
        // For bug detection, we need to check that withdrawAll sends the full balance.
        // To do so without consuming the balance, we can pre-fund with a known amount, then call sendMoney,
        // then call withdrawAll and check that the owner receives exactly (balanceBefore - value).
        // But that would change state.
        // Simpler: after sendMoney, the balance must be exactly (balanceBefore - value).
        // This is always true for any transfer that succeeds.
        // The bug is in a different entry point (withdrawAll).
        // We must detect it through sendMoney and another getter.
        // The bug causes withdrawAll to send 0, but we can't observe that unless we call withdrawAll.
        // So we call withdrawAll after the sendMoney and check the owner's balance change.
        // But that would be a second external call, which is allowed.
        // Let's design: first, ensure owner has some ether from outside (deal).
        // Then call sendMoney with some value, then call withdrawAll, and check owner balance.
        // However, the rule must be general over fuzz params.
        // We'll use vm.prank to set msg.sender to owner and call withdrawAll after sendMoney.
        // The owner should receive exactly the contract's balance at that moment.
        // That balance is (balanceBefore - value).
        // In the bug, owner receives 0.

        // But the original test rule was: 'After any successful sendMoney call, the contract's balance must equal 0 times a certain factor, or more precisely: after sendMoney, withdrawAll() should be callable and the contract's balance should be 0.' — that already failed.
        // So we need a different rule that holds for P and fails for M.
        // Let's check the invariant that after a sendMoney, the total deposits count remains unchanged, but for the bug, it's also unchanged. Another invariant: the owner address is unchanged. True for both.
        // The crucial difference is in the implementation of withdrawAll: P sends all balance, M sends 0.
        // To detect this, we must trigger withdrawAll after sendMoney and compare the owner's balance change.
        // But the test must end with exactly one assertTrue over the fuzz parameters and getters.
        // We can define a helper property: after a sendMoney and then a withdrawAll, the owner's balance increase equals (balanceBefore - value). In M, it equals 0.
        // So the assertion is: if we call sendMoney(a, v) then withdrawAll(), then owner's balance increase is either (prevBalance - v) or 0.
        // But we need a formula that is always true for P and conditionally false for M.
        // Actually, for any given v, after sendMoney and withdrawAll, the owner's balance increase must equal the contract balance before withdrawAll.
        // The contract balance before withdrawAll is (balanceBefore - v) (since sendMoney reduced it).
        // So the rule: ownerETHreceived == balanceBefore - v.
        // This holds for P, fails for M (0 != balanceBefore - v unless balanceBefore == v, which is not always true).

        // Let's implement this:
        uint256 ownerBalBefore = c.owner().balance;
        uint256 balBefore = address(c).balance;
        c.sendMoney(target, value);
        // After sendMoney, the contract's balance is balBefore - value.
        // Now call withdrawAll. We need to be owner.
        vm.prank(c.owner());
        c.withdrawAll();
        uint256 ownerBalAfter = c.owner().balance;
        uint256 ownerReceived = ownerBalAfter - ownerBalBefore;
        // The expected received amount is the contract balance just before withdrawAll call.
        // That balance is balBefore - value.
        // So we assert:
        assertTrue(ownerReceived == balBefore - value, "WithdrawAll should send full balance after sendMoney");
    }
}

